import json
import os
import re
import uuid
from datetime import datetime
from typing import Optional

from langchain_core.messages import messages_from_dict, messages_to_dict

from config import (
    CONVERSATIONS_DIR,
    CONVERSATION_TITLE_MAX_LENGTH,
    NEW_CONVERSATION_ID,
    NEW_CONVERSATION_TITLE,
)
from config.constants import MessageRole

# IDs are generated by save(); anything else (e.g. "../x") could escape base_dir.
_ID_PATTERN = re.compile(r"[0-9a-f]{32}")


class ConversationStore:
    """Manages conversation persistence to disk (one JSON file per conversation)."""

    def __init__(self, base_dir: str = None):
        """
        Initialize ConversationStore.

        Args:
            base_dir: Directory for storing conversations
        """
        self.base_dir = base_dir or str(CONVERSATIONS_DIR)
        os.makedirs(self.base_dir, exist_ok=True)

    def save(
        self,
        conversation_id: str,
        messages: list[dict],
        model: str,
        memory_messages: list = None,
        title: str = None,
    ) -> str:
        """
        Save a conversation to disk, replacing any earlier version of it.

        Args:
            conversation_id: ID of the conversation, or NEW_CONVERSATION_ID
            messages: List of message dictionaries
            model: Model name used for this conversation
            memory_messages: Optional LangChain memory messages
            title: Optional conversation title

        Returns:
            The conversation ID (newly generated for new conversations)
        """
        if not messages:
            return ""

        # Generate title from first user message if not provided
        if not title or title == NEW_CONVERSATION_TITLE:
            first_user_msg = next(
                (msg for msg in messages if msg["role"] == MessageRole.USER.value),
                None,
            )
            if first_user_msg:
                title = first_user_msg["content"][:CONVERSATION_TITLE_MAX_LENGTH].strip()

        if conversation_id == NEW_CONVERSATION_ID:
            conversation_id = uuid.uuid4().hex

        conversation_data = {
            "messages": messages,
            "model": model,
            "memory": messages_to_dict(memory_messages or []),
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "title": title,
        }

        filepath = self._path(conversation_id)
        temp_path = f"{filepath}.tmp"
        with open(temp_path, "w", encoding="utf-8") as f:
            json.dump(conversation_data, f, ensure_ascii=False)
        os.replace(temp_path, filepath)  # atomic: a crash never leaves half a file

        return conversation_id

    def load(self, conversation_id: str) -> Optional[dict]:
        """
        Load a conversation from disk.

        Args:
            conversation_id: ID of the conversation to load

        Returns:
            Conversation data dictionary or None
        """
        try:
            with open(self._path(conversation_id), encoding="utf-8") as f:
                data = json.load(f)
            data["memory"] = messages_from_dict(data.get("memory") or [])
            return data
        except (OSError, ValueError, KeyError, TypeError, AttributeError):
            return None

    def delete(self, conversation_id: str) -> bool:
        """
        Delete a conversation from disk.

        Args:
            conversation_id: ID of the conversation to delete

        Returns:
            True if deletion was successful
        """
        try:
            os.remove(self._path(conversation_id))
            return True
        except (OSError, ValueError):
            return False

    def list_all(self) -> list[tuple[str, str]]:
        """
        List all saved conversations, newest first.

        Returns:
            List of tuples (conversation_id, display_name)
        """
        conversations = []

        if not os.path.exists(self.base_dir):
            return conversations

        for filename in os.listdir(self.base_dir):
            conversation_id, extension = os.path.splitext(filename)
            if extension != ".json" or not _ID_PATTERN.fullmatch(conversation_id):
                continue

            try:
                with open(os.path.join(self.base_dir, filename), encoding="utf-8") as f:
                    data = json.load(f)

                title = data.get("title", "")
                if not title:
                    first_msg = next(
                        (msg["content"] for msg in data.get("messages", [])
                         if msg["role"] == MessageRole.USER.value),
                        "",
                    )
                    title = first_msg[:CONVERSATION_TITLE_MAX_LENGTH]
                    if len(first_msg) > CONVERSATION_TITLE_MAX_LENGTH:
                        title += "..."

                timestamp = data.get("timestamp", "Unknown date")
                model = data.get("model", "unknown")
                display_name = f"{timestamp[:10]} - {model}: {title}"

                conversations.append((timestamp, conversation_id, display_name))

            except (OSError, ValueError, KeyError, TypeError, AttributeError):
                continue  # unreadable or corrupt file: skip it, keep the rest

        conversations.sort(reverse=True)
        return [(conversation_id, name) for _, conversation_id, name in conversations]

    def _path(self, conversation_id: str) -> str:
        """Return the file path for a conversation ID, rejecting anything else."""
        if not isinstance(conversation_id, str) or not _ID_PATTERN.fullmatch(conversation_id):
            raise ValueError(f"Invalid conversation id: {conversation_id!r}")
        return os.path.join(self.base_dir, f"{conversation_id}.json")
